"use client";

import React from "react";
import {
  ShaderBackground,
  type ShaderBackgroundProps,
} from "@/registry/components/shader-background";

export type NoiseBackgroundProps = Omit<ShaderBackgroundProps, "preset" | "flareOrigin" | "rayCount" | "glowRadius" | "lensStreak" | "logo">;

/**
 * Standalone Noise WebGL background component powered by the shared RenderJoy shader engine.
 */
export function NoiseBackground(props: NoiseBackgroundProps) {
  return <ShaderBackground preset="noise" {...props} />;
}
